module adder_32bit(
    input [32:1] A,
    input [32:1] B,
    output reg [32:1] S,
    output reg C32
);
    // TODO: Your code
    reg [32:1] P, G;
    reg [32:1] C;
    integer i;
    always @(*) begin
        for (i = 1; i <= 32; i = i + 1) begin
            P[i] = A[i] ^ B[i];
            G[i] = A[i] & B[i];
        end
        C[1] = 0;
        for (i = 2; i <= 32; i = i + 1) begin
            C[i] = G[i-1] | (P[i-1] & C[i-1]);
        end
        for (i = 1; i <= 32; i = i + 1) begin
            S[i] = P[i] ^ C[i];
        end
        C32 = G[32] | (P[32] & C[32]);
    end
endmodule
